    private void queueExplicit(Intent intent){if((intent.getFlags()&Intent.FLAG_ACTIVITY_LAUNCHED_FROM_HISTORY)!=0){pendingActions.cancel("HISTORY");return;}String action=intent.getStringExtra("m1Action");if(action==null)return;if(!Arrays.asList("STAGE_BINDING","CLOSE","STATUS").contains(action)){pendingActions.cancel("NONFLIGHT_ACTION_REJECTED");error(new IOException("VISIBLE_NATIVE_CONNECT_AND_FLIGHT_TOUCH_ONLY"));return;}try{long n=SystemClock.elapsedRealtimeNanos();pendingActions.enqueue(intent.getStringExtra("m1ActionId"),action,new Intent(intent),n);android.util.Log.i("AERIS_CONTROL_INTENT","QUEUED "+action+" foreground="+foreground+" atNs="+n);handler.post(this::drainExplicit);}catch(Exception e){error(e);}}
