        config=new ControlConfig(expected,observed,bindingSHA,name->{try(InputStream in=getAssets().open(name)){return readBounded(in,65536);}});
        if(workspace==null||workspace.latestDraft()==null||!"preflight".equals(chosenView))throw new IOException("SAVED_SURVEY_AND_PREFLIGHT_REQUIRED");prepareSessionLink();if(!writeProbe())throw new IOException("ACTUAL_MINIMAL_ANDROID_PROFILE_NOT_OBSERVED");
        ControlOwner next=new ControlOwner(getFilesDir(),config,clock,sync,()->foreground,this::update,controls.source,IoTiming.androidCpu(),nativeSourceSHA(),viewEpoch);owner=next;
        if(sampler!=null)sampler.close();final ScheduledThreadPoolExecutor executor=new ScheduledThreadPoolExecutor(1,r->new Thread(r,"aeris-native07-input-sampler"));executor.setRemoveOnCancelPolicy(true);executor.setExecuteExistingDelayedTasksAfterShutdownPolicy(false);executor.setContinueExistingPeriodicTasksAfterShutdownPolicy(false);
