    private void prepareSessionLink()throws Exception{File file=workspace.latestDraft();byte[]bytes=WorkspaceStore.read(file);JSONObject draft=new JSONObject(new String(bytes,StandardCharsets.UTF_8));sessionDraftSHA=Values.hash(bytes);sessionLink=new JSONObject();sessionLink.put("run",config.context.run);sessionLink.put("epoch",config.context.epoch);sessionLink.put("boot",config.context.boot);sessionLink.put("generation",config.context.generation);sessionLink.put("operator",config.context.operator);sessionLink.put("profileId",config.context.profileId);sessionLink.put("APSHA256",config.expected.binarySHA256);sessionLink.put("modelSHA256",config.expected.modelSHA256);sessionLink.put("configSHA256",config.expected.configSHA256);sessionLink.put("surveyRevision",draft.getInt("revision"));sessionLink.put("surveySHA256",sessionDraftSHA);try(InputStream source=getAssets().open("source-identity.json")){JSONObject identity=new JSONObject(new String(readBounded(source,16384),StandardCharsets.UTF_8));if(!identity.getString("sourceSHA256").matches("[a-f0-9]{64}"))throw new IOException("SOURCE_IDENTITY_SHA");sessionLink.put("sourceIdentity",identity);sessionLink.put("sourceSHA256",identity.getString("sourceSHA256"));}sessionLink.put("authorityRestorable",false);File links=new File(getFilesDir(),"review-links");if(!links.isDirectory()&&!links.mkdir())throw new IOException("LINK_DIRECTORY");File dest=new File(links,config.context.run+".json");if(dest.exists())throw new IOException("SESSION_LINK_RUN_REUSE");atomic(dest,sessionLink.toString().getBytes(StandardCharsets.UTF_8));sync.directory(getFilesDir());reviewQueued=false;}
